{
  "title": "The Glass Diver's Escape",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The ruined gates loom ahead.",
      "visual_description": "Cracked stone archway with rusted iron gates, old royal banners tattered in the wind, and the glass diver standing before it.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 2,
      "caption": "Mara checks her compass at the entrance.",
      "visual_description": "Mara the Cartographer kneels by a broken pillar, ink-stained coat flapping, brass compass glowing faintly as she studies the path.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 3,
      "caption": "The Oracle Lamp flickers a warning.",
      "visual_description": "The Oracle Lamp sits on a stone, its single eye in the flame darting, casting long shadows across the cracked courtyard.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 4,
      "caption": "Glass Diver leaps through a shattered window.",
      "visual_description": "Glass Diver dives through a broken stained-glass window, helmet clear, coat reflecting the shattered colors of the city.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 5,
      "caption": "Tin Fox scouts ahead among rubble.",
      "visual_description": "Tin Fox scurries over fallen stones, key-wind tail ticking, blue glass eyes scanning for danger under the moonlight.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "Mara maps a cursed tower in the distance.",
      "visual_description": "Mara stands on a collapsed wall, sketching a twisted tower with dark smoke curling from its peak, her ink-stained hands steady.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 7,
      "caption": "Oracle Lamp warns of armored patrols nearby.",
      "visual_description": "The Oracle Lamp's flame winks rapidly, its eye widening as the sound of heavy footsteps echoes from a side street.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 8,
      "caption": "Glass Diver hides in a mirror's reflection.",
      "visual_description": "Glass Diver presses against a cracked mirror on a wall, his form shimmering as he merges with the reflective surface to avoid detection.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 9,
      "caption": "Tin Fox finds a hidden passage.",
      "visual_description": "Tin Fox noses at a loose stone beneath an old royal banner, revealing a dark tunnel entrance with a faint breeze.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 10,
      "caption": "Mara leads the group through the passage.",
      "visual_description": "Mara holds her compass high, leading Glass Diver and Tin Fox through the narrow, cobwebbed tunnel, the Oracle Lamp bobbing behind.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 11,
      "caption": "The Sleeping Tax Collector blocks the way.",
      "visual_description": "The Sleeping Tax Collector slumps against a magic door, ledger book under head, stamped papers stuck to his sleeves, snoring softly.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 12,
      "caption": "Glass Diver swims through a window into the chamber.",
      "visual_description": "Glass Diver emerges from a high window, landing silently in the dusty chamber, his helmet catching the dim light.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 13,
      "caption": "Oracle Lamp illuminates the magic door's runes.",
      "visual_description": "The Oracle Lamp casts a warm glow on the magic door, revealing glowing runes that pulse as the flame eye studies them.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 14,
      "caption": "Mara deciphers the door's puzzle.",
      "visual_description": "Mara traces the runes with her ink-stained fingers, her compass needle spinning as she mutters the solution, tired but focused.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 15,
      "caption": "The magic door swings open with a groan.",
      "visual_description": "The heavy stone door grinds open, revealing a torch-lit corridor leading toward the outer wall and the bridge beyond.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 16,
      "caption": "The group races across the courtyard.",
      "visual_description": "The rescue party dashes through the ruined courtyard, old banners whipping in the wind, the Oracle Lamp bobbing frantically.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 17,
      "caption": "Glass Diver carries the Tax Collector to the bridge.",
      "visual_description": "Glass Diver hoists the Sleeping Tax Collector over his shoulder, sprinting onto the stone bridge that spans a dark ravine.",
      "characters": ["glass_diver", "sleeping_tax_collector"]
    },
    {
      "scene_number": 18,
      "caption": "The bridge shatters behind them but they escape.",
      "visual_description": "The bridge crumbles into the chasm as the group reaches the far side, the ruined city silhouetted against a blood-red sky, all five characters together safe.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    }
  ]
}

